import os,sys,base64,zlib,subprocess,struct,tempfile,ctypes,platform,hashlib
try:
    from Crypto.Cipher import AES
except ImportError:
    sys.exit(1)

P=""
KP=""
OS_TYPE = platform.system().lower()

def get_hwid():
    try:
        aid = subprocess.check_output(['settings', 'get', 'secure', 'android_id'], stderr=subprocess.DEVNULL).decode('utf-8').strip()
        if aid and len(aid) == 16 and aid != "null":
            return aid
    except Exception: pass
    
    homedir = os.environ.get("HOME") or os.environ.get("USERPROFILE")
    if homedir:
        p = os.path.join(homedir, ".nasr_hwid")
        if os.path.exists(p):
            with open(p, "r") as f: return f.read().strip()
            
    try:
        import uuid
        return str(uuid.getnode()).strip()
    except Exception: pass
    return ""

FK = hashlib.sha256(get_hwid().encode('utf-8')).digest()

def aes_decrypt(data, key):
    nonce = data[:16]
    tag = data[16:32]
    ciphertext = data[32:]
    cipher = AES.new(key, AES.MODE_EAX, nonce=nonce)
    return cipher.decrypt_and_verify(ciphertext, tag)

def _ghost_run():
 try:
  kd=zlib.decompress(aes_decrypt(base64.b64decode(KP), FK))
  off=0;sks=[]
  while off<len(kd):
   l=struct.unpack("<I",kd[off:off+4])[0];off+=4
   sks.append(kd[off:off+l]);off+=l
   
  pd=zlib.decompress(aes_decrypt(base64.b64decode(P), FK))
  off=0;shs=[]
  for i in range(len(sks)):
   if off+4>len(pd):break
   l=struct.unpack("<I",pd[off:off+4])[0];off+=4
   enc=pd[off:off+l];off+=l
   shs.append(zlib.decompress(aes_decrypt(enc, sks[i])))
  full_bin=b"".join(shs)
  v = os.environ.copy()
  if hasattr(sys, 'prefix'): v["PYTHONHOME"] = sys.prefix
  suffix = ".exe" if OS_TYPE == 'windows' else ""
  f,p=tempfile.mkstemp(prefix=".g_", suffix=suffix)
  os.write(f,full_bin);os.close(f)
  if OS_TYPE != 'windows': os.chmod(p,0o700)
  subprocess.Popen([p] + sys.argv[1:], env=v).wait()
  try:os.remove(p)
  except:pass
 except Exception as e: pass

if __name__=="__main__":_ghost_run()
